#!/bin/sh
# Validate only files generated by harness-kit, not the product's code quality.

set -eu

project_root=${1:-.}
project_root=$(cd "$project_root" && pwd)
errors=0

for required_file in AGENTS.md harness.toml docs/INTENT.md docs/LLM_WIKI.md docs/PRD.md scripts/harness.sh; do
    if [ ! -f "$project_root/$required_file" ]; then
        printf '%s\n' "missing required file: $required_file" >&2
        errors=1
    fi
done

if [ -f "$project_root/docs/ARCHITECTURE.md" ]; then
    printf '%s\n' "info: architecture document present"
fi
if [ -f "$project_root/docs/ADR/0000-template.md" ]; then
    printf '%s\n' "info: ADR template present"
fi

for search_path in "$project_root/AGENTS.md" "$project_root/docs" "$project_root/.harness/README.md" "$project_root/.harness/IMPLEMENTATION.md"; do
    if [ -e "$search_path" ] && grep -R -q '{{' "$search_path" 2>/dev/null; then
        printf '%s\n' "unresolved template token under: $search_path" >&2
        errors=1
    fi
done

if [ "$errors" -ne 0 ]; then
    printf '%s\n' "Harness validation failed." >&2
    exit 1
fi

printf '%s\n' "Harness validation passed: $project_root"
